step.cypher:
CYPHER 25 CALL gds.graph.project('g_kmeans', {EntityDetail: {properties: ['composite_proj']}}, '*') YIELD nodeCount
// Try multiple k values, select best silhouette CALL gds.kmeans.mutate('g_kmeans', { nodeProperty: 'composite_proj', k: 10, maxIterations: 25, numberOfRestarts: 10, computeSilhouette: true, randomSeed: 42, mutateProperty: 'cluster_topo' }) YIELD communityDistribution, averageSilhouette
CALL gds.graph.nodeProperties.write('g_kmeans', ['cluster_topo']) YIELD propertiesWritten RETURN propertiesWritten, averageSilhouette

phase.cypher:
CYPHER 25 // Get distinct subsystem IDs with member counts MATCH (n:EntityDetail {namespace: $namespace}) WHERE n.subsystem_id IS NOT NULL WITH n.subsystem_id AS sid, collect(n) AS members, count(n) AS member_count
// Create SubsystemNavigator CREATE (sub:SubsystemNavigator { namespace: $namespace, subsystem_id: sid, hierarchy_level: 1, member_count: member_count, created_at: datetime(), created_by: 'grothendieck_v3', status: 'DETECTED' })
// Link to NavigationMaster WITH sub, members MATCH (nav:NavigationMaster {namespace: $namespace}) CREATE (nav)-[:HAS_SUBSYSTEM]->(sub)
// Link each file to its subsystem WITH sub, members UNWIND members AS m CREATE (sub)-[:CONTAINS]->(m)
RETURN sub.subsystem_id AS id, sub.member_count AS files
